<?php

declare(strict_types=1);

namespace Nowo\ShortLinkBundle\Domain\Model;

use Nowo\ShortLinkBundle\Domain\Exception\InvalidShortLinkArgumentException;

use function preg_match;

/**
 * Id of a short link: a UUID (v7 when generated by the bundle) as a lowercase 36-character string (221 convention).
 * UUIDv7 ids sort by creation time, which the list keyset relies on.
 */
final readonly class ShortLinkId
{
    private const PATTERN = '/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/D';

    private function __construct(public string $value)
    {
    }

    /**
     * From a stored or submitted id (lowercase canonical form only).
     *
     * @throws InvalidShortLinkArgumentException when the value is not a lowercase UUID
     */
    public static function fromString(string $value): self
    {
        if (preg_match(self::PATTERN, $value) !== 1) {
            throw new InvalidShortLinkArgumentException('A short-link id is a lowercase UUID.');
        }

        return new self($value);
    }

    /**
     * Exact comparison.
     */
    public function equals(self $other): bool
    {
        return $this->value === $other->value;
    }
}
